SELECT /*+ S603 UI  시간별 송수신처리현황(ID별) TimeLogCntVO 황용길 */  ifd ,  DECODE(src, 'S', '송신', 'R', '수신', '차이') src ,  sc ,  (    SELECT HOST_NAME    FROM TB_S60_SYST020    WHERE eai_system_id = sc) scname ,  tot,  t07 ,  t08 ,  t09 ,  t10 ,  t11 ,  t12 ,  t13 ,  t14 ,  t15 ,  t16 ,  t17 ,  t18 ,  t19 ,  t20 ,  t21 ,  t22 ,  t23 ,  t00 ,  t01 ,  t02 ,  t03 ,  t04 ,  t05 ,  t06FROM (    SELECT eai_interface_id ifd ,      send_receive_code src ,      UPPER(eai_system_id) sc ,      SUM(NVL(data_count , 0)) AS tot ,      SUM(NVL(time_count7 , 0)) AS t07 ,      SUM(NVL(time_count8 , 0)) AS t08 ,      SUM(NVL(time_count9 , 0)) AS t09 ,      SUM(NVL(time_count10, 0)) AS t10 ,      SUM(NVL(time_count11, 0)) AS t11 ,      SUM(NVL(time_count12, 0)) AS t12 ,      SUM(NVL(time_count13, 0)) AS t13 ,      SUM(NVL(time_count14, 0)) AS t14 ,      SUM(NVL(time_count15, 0)) AS t15 ,      SUM(NVL(time_count16, 0)) AS t16 ,      SUM(NVL(time_count17, 0)) AS t17 ,      SUM(NVL(time_count18, 0)) AS t18 ,      SUM(NVL(time_count19, 0)) AS t19 ,      SUM(NVL(time_count20, 0)) AS t20 ,      SUM(NVL(time_count21, 0)) AS t21 ,      SUM(NVL(time_count22, 0)) AS t22 ,      SUM(NVL(time_count23, 0)) AS t23 ,      SUM(NVL(time_count0 , 0)) AS t00 ,      SUM(NVL(time_count1 , 0)) AS t01 ,      SUM(NVL(time_count2 , 0)) AS t02 ,      SUM(NVL(time_count3 , 0)) AS t03 ,      SUM(NVL(time_count4 , 0)) AS t04 ,      SUM(NVL(time_count5 , 0)) AS t05 ,      SUM(NVL(time_count6 , 0)) AS t06    FROM TB_S60_SUMM010    WHERE EAI_SEND_DATE = REPLACE(?, '-', '')      AND EAI_INTERFACE_ID LIKE ? || '%'    GROUP BY eai_interface_id, send_receive_code, eai_system_id    UNION ALL    SELECT ifd ,      'C' src ,      '' sc ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN tot*NVL(mrc, 1) ELSE tot*(-1) END), 0)) tot ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t07*NVL(mrc, 1) ELSE t07*(-1) END), 0)) t07 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t08*NVL(mrc, 1) ELSE t08*(-1) END), 0)) t08 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t09*NVL(mrc, 1) ELSE t09*(-1) END), 0)) t09 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t10*NVL(mrc, 1) ELSE t10*(-1) END), 0)) t10 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t11*NVL(mrc, 1) ELSE t11*(-1) END), 0)) t11 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t12*NVL(mrc, 1) ELSE t12*(-1) END), 0)) t12 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t13*NVL(mrc, 1) ELSE t13*(-1) END), 0)) t13 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t14*NVL(mrc, 1) ELSE t14*(-1) END), 0)) t14 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t15*NVL(mrc, 1) ELSE t15*(-1) END), 0)) t15 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t16*NVL(mrc, 1) ELSE t16*(-1) END), 0)) t16 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t17*NVL(mrc, 1) ELSE t17*(-1) END), 0)) t17 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t18*NVL(mrc, 1) ELSE t18*(-1) END), 0)) t18 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t19*NVL(mrc, 1) ELSE t19*(-1) END), 0)) t19 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t20*NVL(mrc, 1) ELSE t20*(-1) END), 0)) t20 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t21*NVL(mrc, 1) ELSE t21*(-1) END), 0)) t21 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t22*NVL(mrc, 1) ELSE t22*(-1) END), 0)) t22 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t23*NVL(mrc, 1) ELSE t23*(-1) END), 0)) t23 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t00*NVL(mrc, 1) ELSE t00*(-1) END), 0)) t00 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t01*NVL(mrc, 1) ELSE t01*(-1) END), 0)) t01 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t02*NVL(mrc, 1) ELSE t02*(-1) END), 0)) t02 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t03*NVL(mrc, 1) ELSE t03*(-1) END), 0)) t03 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t04*NVL(mrc, 1) ELSE t04*(-1) END), 0)) t04 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t05*NVL(mrc, 1) ELSE t05*(-1) END), 0)) t05 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t06*NVL(mrc, 1) ELSE t06*(-1) END), 0)) t06    FROM (        SELECT EAI_INTERFACE_ID ifd ,          UPPER(EAI_SYSTEM_ID) sys ,          SEND_RECEIVE_CODE sr ,          DATA_COUNT tot,          TIME_COUNT0 t00,          TIME_COUNT1 t01,          TIME_COUNT2 t02,          TIME_COUNT3 t03 ,          TIME_COUNT4 t04,          TIME_COUNT5 t05,          TIME_COUNT6 t06,          TIME_COUNT7 t07,          TIME_COUNT8 t08 ,          TIME_COUNT9 t09,          TIME_COUNT10 t10,          TIME_COUNT11 t11,          TIME_COUNT12 t12,          TIME_COUNT13 t13 ,          TIME_COUNT14 t14,          TIME_COUNT15 t15,          TIME_COUNT16 t16,          TIME_COUNT17 t17,          TIME_COUNT18 t18 ,          TIME_COUNT19 t19,          TIME_COUNT20 t20,          TIME_COUNT21 t21,          TIME_COUNT22 t22,          TIME_COUNT23 t23        FROM TB_S60_SUMM010        WHERE EAI_SEND_DATE = REPLACE(?, '-', '')          AND EAI_INTERFACE_ID LIKE ? || '%' ) Summ ,      (        SELECT EAI_INTERFACE_ID ,          MIN(MULTI_RECV_COUNT) mrc        FROM TB_S60_IFMG020        GROUP BY EAI_INTERFACE_ID  ) Dinf    WHERE Summ.ifd = Dinf.EAI_INTERFACE_ID (+)    GROUP BY ifd )ORDER BY ifd , src